files.src/build_order.py:
"""Deterministic build ordering with cycle reporting. See instructions.md."""


class CycleError(ValueError):
    """Raised when no build order exists.

    ``cycle`` is a closed path such as ``["a", "b", "a"]`` (each node depends on the next).
    """

    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle: " + " -> ".join(self.cycle))


def build_order(deps):
    raise NotImplementedError

files.tests/test_build_order.py:
import pytest

from build_order import CycleError, build_order


def test_diamond_order():
    deps = {"d": ["b", "c"], "b": ["a"], "c": ["a"], "a": []}
    assert build_order(deps) == ["a", "b", "c", "d"]


def test_dependency_only_node_is_included():
    assert build_order({"app": ["lib"]}) == ["lib", "app"]


def test_cycle_reports_path():
    with pytest.raises(CycleError) as info:
        build_order({"a": ["b"], "b": ["a"]})
    assert info.value.cycle == ["a", "b", "a"]

